from datetime import date, timedelta
from typing import List, Optional

class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: Optional[List[date]] = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = holidays or []
        # Track used leave days per employee per year
        # Structure: {employee: {year: days_used}}
        self.used_days = {}

    def _is_weekend(self, d: date) -> bool:
        """Check if a date is Saturday (5) or Sunday (6)"""
        return d.weekday() >= 5

    def _is_holiday(self, d: date) -> bool:
        """Check if a date is in the holidays list"""
        return d in self.holidays

    def _is_working_day(self, d: date) -> bool:
        """Check if a date is a working day (not weekend and not holiday)"""
        return not self._is_weekend(d) and not self._is_holiday(d)

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        """Request leave from start to end (inclusive); returns the number of leave days used."""
        # Check if end date is before start date
        if end < start:
            raise ValueError("End date cannot be before start date")

        # Check if request is made less than 3 days before start date
        if (start - today).days < 3:
            raise ValueError("Leave request must be made at least 3 days before start date")

        # Calculate the number of working days in the range [start, end] inclusive
        current = start
        leave_days = 0

        while current <= end:
            if self._is_working_day(current):
                leave_days += 1
            current += timedelta(days=1)

        # Get the year for this leave period (use start year as reference)
        year = start.year

        # Initialize tracking for this employee if not exists
        if employee not in self.used_days:
            self.used_days[employee] = {}

        # Initialize year tracking if not exists
        if year not in self.used_days[employee]:
            self.used_days[employee][year] = 0

        # Check if we have enough remaining days
        remaining_days = self.remaining(employee, year)
        if leave_days > remaining_days:
            # We'll use up all remaining days, but the request is still valid
            # The requirement doesn't say to reject over-request, just return actual used days
            pass

        # Update used days
        self.used_days[employee][year] += leave_days

        return leave_days

    def remaining(self, employee: str, year: int) -> int:
        """Return remaining leave days for an employee in a given year."""
        # Get used days for this employee and year, default to 0 if not found
        used = self.used_days.get(employee, {}).get(year, 0)
        return max(0, self.days_per_year - used)
